// Con los números de la tabla de R8: ¿cuánto se achica y cuánto más se tarda?
const sin = { apk: 4538309, dex: 8401748, metodos: 58874, segundos: 28.7 };
const con = { apk: 1594839, dex: 1182912, metodos: 9970, segundos: 54.8 };
const pct = (a, b) => (100 * (1 - b / a)).toFixed(1) + ' %';
console.log('APK achicado:', pct(sin.apk, con.apk));
console.log('DEX achicado:', pct(sin.dex, con.dex));
console.log('Métodos menos:', pct(sin.metodos, con.metodos));
console.log('Tiempo extra:', (100 * (con.segundos / sin.segundos - 1)).toFixed(1) + ' %');
console.log('Bytes ahorrados por segundo extra:',
  Math.round((sin.apk - con.apk) / (con.segundos - sin.segundos)));
